SELECT rd.purchase_receipt_detail_id AS purchaseReceiptDetailId, rh.purchase_receipt_id AS purchaseReceiptId, rh.receipt_no AS receiptNo, rh.use_at AS useAt, rd.receipt_qty AS receiptQty, rd.closing_month AS closingMonth FROM tb_purchase_receipt_hd rh JOIN tb_purchase_receipt_dt rd ON rd.purchase_receipt_id = rh.purchase_receipt_id AND rd.tenant_id = rh.tenant_id WHERE rh.tenant_id = #{tenantId, jdbcType=BIGINT} AND rd.purchase_receipt_detail_id IN
#{detailId, jdbcType=BIGINT}
ORDER BY rh.purchase_receipt_id, rd.purchase_receipt_detail_id FOR UPDATE OF rh, rd
